-- Migration: tabela de links do site por marca + campo produto em lives

-- ── Tabela site_links ────────────────────────────────────────────
create table if not exists site_links (
  id         uuid primary key default gen_random_uuid(),
  brand      text not null,
  categoria  text not null,
  produto    text not null,
  link       text not null,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

alter table site_links enable row level security;
do $$ begin
  if not exists (
    select 1 from pg_policies where tablename = 'site_links' and policyname = 'allow all on site_links'
  ) then
    execute 'create policy "allow all on site_links" on site_links for all using (true) with check (true)';
  end if;
end $$;

create index if not exists idx_site_links_brand on site_links (brand);

-- ── Campo produto em lives (para beleza brands) ──────────────────
alter table lives add column if not exists produto text;

